-- ---------------------------------------------------------------------------
-- The firms, as businesses
--
-- A company on Medosha is two things: a profile somebody can hire through, and
-- a listing in the business directory. Creating only the first would leave
-- eight firms that answer a professional search and cannot be found by anybody
-- browsing companies, which is a difference nobody outside the schema would
-- expect.
--
-- `is_claimed` is true and `owner_id` points at the profile, because these are
-- not scraped listings waiting for somebody to claim them.
-- ---------------------------------------------------------------------------

insert into public.companies (
  slug, name, category, description, city, country,
  employees_count, owner_id, is_claimed, verified, import_source, external_ref
)
values
  ('gerji-wood-works', 'Gerji Wood Works', 'joinery', 'Kitchens, wardrobes and office furniture, made in the workshop in Gerji and fitted on site. Fourteen people, nine years in business.', 'Addis Ababa', 'Ethiopia', 14, 'efad828d-fc1d-5ced-849b-bf7074718098'::uuid, true, false, 'seed', 'gerji_wood_works'),
  ('kazanchis-electrical-contractors', 'Kazanchis Electrical Contractors', 'electrical', 'Electrical contracting for apartment blocks and offices: wiring, boards, generators and standby. Twelve years, and works across the city.', 'Addis Ababa', 'Ethiopia', 26, '183ea4df-b3d7-510e-bb31-715d0a335077'::uuid, true, false, 'seed', 'kazanchis_electrical'),
  ('lebu-metal-&-aluminium-works', 'Lebu Metal & Aluminium Works', 'joinery', 'Aluminium windows, curtain walling and shopfronts, plus steel gates and handrails. Own workshop at Lebu.', 'Addis Ababa', 'Ethiopia', 18, '317736dd-036c-50bc-bfe3-6af399b78919'::uuid, true, false, 'seed', 'lebu_metal_works'),
  ('summit-interiors-&-fit-out', 'Summit Interiors & Fit-out', 'interior', 'Office and restaurant fit-out from drawings through to handover. Small team, one project at a time.', 'Addis Ababa', 'Ethiopia', 11, '3b6f39b9-d57d-556c-a6fe-8035c28e06ca'::uuid, true, false, 'seed', 'summit_interiors'),
  ('kolfe-scaffolding-&-formwork', 'Kolfe Scaffolding & Formwork', 'general-contracting', 'Scaffold and formwork hire with erection and striking included. Ten years supplying contractors on the western side of the city.', 'Addis Ababa', 'Ethiopia', 32, 'fdb9878c-0214-5823-83ab-6c8bc36507c3'::uuid, true, false, 'seed', 'kolfe_scaffolding'),
  ('gotera-plumbing-&-sanitary', 'Gotera Plumbing & Sanitary', 'plumbing', 'Plumbing and sanitary installation for houses and small apartment buildings, including tanks and booster pumps.', 'Addis Ababa', 'Ethiopia', 9, '506f6981-1c9c-527b-8f79-cf7443ef92af'::uuid, true, false, 'seed', 'gotera_plumbing'),
  ('shola-gypsum-&-ceiling', 'Shola Gypsum & Ceiling', 'finishing', 'Gypsum ceilings, partitions and bulkheads. Five years, mostly apartment finishing work in Yeka.', 'Addis Ababa', 'Ethiopia', 15, 'b10b7d37-6c67-5aa1-84d2-37c3406981c1'::uuid, true, false, 'seed', 'shola_gypsum'),
  ('lideta-building-contractors', 'Lideta Building Contractors', 'general-contracting', 'General contracting: villas, G+4 residential and renovation. Fifteen years, sixty-four people, and works across Addis Ababa.', 'Addis Ababa', 'Ethiopia', 64, 'a2227784-7113-5170-af22-a1b5b1637e17'::uuid, true, false, 'seed', 'lideta_contractors')
on conflict (import_source, external_ref) do nothing;

